    frame(lua_state, 31.0);
    if is_excute(agent) {
        ArticleModule::generate_article(boma, *FIGHTER_SNAKE_GENERATE_ARTICLE_C4_SWITCH, false, 0);
    }
    frame(lua_state, 80.0);
    FT_MOTION_RATE(agent, 1.0);
